/* WILDFIRE WATCH - a live p0pc0rn app (non-agentic: it checks on its own; Juli does not work in it). It watches current US wildfire incidents (NIFC / WFIGS) within a distance the person
   picks around ONE place they type in, and posts each NOTABLE fire into Juli's chat once: 100 acres or more, or any size within 25
   miles. Checks run only while p0pc0rn is open: every 90 minutes while a notable fire is in range, every 12 hours when it is calm.
   Data: the national wildfire incident service through the host (p0.fetch). The place is kept on this phone only. */

// ===== SLOTS =====
const SL = window.SLOTS || {};
const TITLE = String(SL.title || 'Wildfire Watch').slice(0, 22);
const ACCENT = /^#[0-9a-fA-F]{6}$/.test(SL.accent || '') ? SL.accent : '#ff6a3d';
const RADII = [25, 50, 100];
const RADIUS0 = RADII.includes(+SL.radius_mi) ? +SL.radius_mi : 50;
const BIG_ACRES = 100, CLOSE_MI = 25;
const PLACE0 = String(SL.place_hint || '').slice(0, 60);

// ===== STATE (saved) =====
const KEY = 'fire.v1';
let st = { place: null, radius: RADIUS0, seen: [], lastCheck: 0 };
let data = { fires: null, err: null, at: 0, busy: false };
let ui = { query: PLACE0, results: null, searching: false, editing: false, contentH: 900 };
function loadSt() { st = Object.assign({ place: null, radius: RADIUS0, seen: [], lastCheck: 0 }, K.load(KEY, {})); }
function saveSt() { K.save(KEY, st); }
loadSt();

// ===== DISTANCE + THE RULE =====
function miles(a, b) {
  const R = 3958.8, toR = Math.PI / 180, dLat = (b.lat - a.lat) * toR, dLon = (b.lon - a.lon) * toR;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * toR) * Math.cos(b.lat * toR) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
}
const notable = (f) => (f.acres || 0) >= BIG_ACRES || f.mi <= CLOSE_MI;
function inRange(list) {
  return (list || []).map((f) => Object.assign({}, f, { mi: miles(st.place, f) })).filter((f) => f.mi <= st.radius).sort((a, b) => a.mi - b.mi);
}
const acresText = (a) => (a == null ? 'size unknown' : a < 1 ? 'under 1 acre' : Math.round(a).toLocaleString('en-US') + ' acres');

// ===== THE CHECK =====
async function check() {
  loadSt();
  if (!st.place) return { active: false };
  const d = await p0.fetch('fires.wfigs', { lat: st.place.lat, lon: st.place.lon, radiusMi: st.radius });
  const fires = inRange(d.fires);
  let posted = 0;
  for (const f of fires) {
    if (!f.id || st.seen.includes(f.id) || !notable(f)) continue;
    try { await p0.chat.post({ title: (f.name || 'Unnamed') + ' Fire · ' + Math.round(f.mi) + ' mi from ' + st.place.name,
      severity: f.mi <= CLOSE_MI ? 'warning' : 'watch', text: acresText(f.acres) + (f.contained != null ? ', ' + Math.round(f.contained) + '% contained' : '') + '. Follow local officials for evacuation orders.' }); }
    catch (e) { break; }   // the hour's notices are used up: the rest wait for the next check
    st.seen.push(f.id); st.seen = st.seen.slice(-300); saveSt(); posted++;   // remembered at once: never posted twice
  }
  st.lastCheck = Date.now(); saveSt();
  if (p0.mode === 'run') { data.fires = fires; data.at = Date.now(); }
  return { active: fires.some(notable), posted };
}
if (window.p0) p0.onCheck(check);

// ===== DATA =====
async function refresh(quiet) {
  if (!st.place || data.busy || !window.p0) return;
  data.busy = true; data.err = null;
  try {
    const d = await p0.fetch('fires.wfigs', { lat: st.place.lat, lon: st.place.lon, radiusMi: st.radius });
    data.fires = inRange(d.fires); data.at = Date.now();
    if (!quiet) K.toast('Updated', { tone: 'good', icon: 'refresh', ms: 1200 });
  } catch (e) { data.err = String((e && e.message) || e); if (!quiet) K.toast("Couldn't reach the wildfire service", { tone: 'bad', icon: 'alert' }); }
  data.busy = false;
}
async function search() {
  const q = ui.query.trim();
  if (q.length < 2 || ui.searching) return;
  ui.searching = true; ui.results = null;
  try { ui.results = (await p0.fetch('geocode.openmeteo', { name: q })).results || []; if (!ui.results.length) K.toast('No place with that name', { tone: 'warn' }); }
  catch (e) { K.toast("Couldn't search for places", { tone: 'bad' }); }
  ui.searching = false;
}
function choose(r) {
  if (r.cc !== 'US') { K.toast('The wildfire service covers the US only', { tone: 'warn', icon: 'alert', ms: 3000 }); return; }
  st.place = { name: [r.name, r.region].filter(Boolean).join(', ').slice(0, 60), lat: r.lat, lon: r.lon };
  st.seen = []; saveSt(); ui.results = null; ui.editing = false; K.blurInputs();
  K.sfx('success'); data.fires = null; refresh(true);
}

// ===== DRAWING =====
function setup() {
  K.setup({ mode: 'dark', accent: ACCENT });
  K.scene('main', drawMain);
  if (st.place && window.p0 && p0.mode === 'run') refresh(true);
}
function draw() { K.render(); }

function drawMain() {
  K.backdrop({ top: K.C.bg, bottom: K.darken(ACCENT, 0.85), glow: [{ x: K.W * 0.2, y: 60, r: 260, color: K.alpha(ACCENT, 0.16) }] });
  const sub = st.place ? 'Within ' + st.radius + ' mi of ' + st.place.name : 'Pick a place to watch';
  const top = K.navBar.top(sub) + 8, clipY = K.navBar.bottom(), w = K.W - 2 * K.S.l, x = K.S.l;
  const off = K.scroll('main', 0, clipY, K.W, K.H - clipY, ui.contentH);
  K.clip(0, clipY, K.W, K.H - clipY, () => { ui.contentH = body(x, top - off, w) + off - top + 40; });
  const tap = K.navBar(TITLE, off, { sub, right: st.place ? { id: 'refresh', icon: 'refresh' } : undefined });
  if (tap === 'refresh') refresh(false);
}

function body(x, y, w) {
  const y0 = y;
  if (!st.place || ui.editing) y = placePicker(x, y, w);
  else {
    K.card(x, y, w, 64, { r: 16 });
    K.icon('pin', x + 30, y + 32, 20, ACCENT);
    K.text(st.place.name, x + 54, y + 28, 'headline', K.C.text, { maxW: w - 150 });
    K.text(st.lastCheck ? 'Last check ' + K.fmt.ago(st.lastCheck) : 'Not checked yet', x + 54, y + 48, 'footnote', K.C.text3);
    if (K.button('change', x + w - 92, y + 14, 80, 36, 'Change', { style: 'tinted' })) { ui.editing = true; ui.query = ''; ui.results = null; }
    y += 80;
    K.text('DISTANCE', x, y + 14, 'label', K.C.text2); y += 24;
    const ri = K.segmented('radius', x, y, w, RADII.map((r) => r + ' mi'), RADII.indexOf(st.radius));
    if (RADII[ri] !== st.radius) { st.radius = RADII[ri]; saveSt(); refresh(true); }
    y += 52;
    K.text('FIRES IN RANGE', x, y + 14, 'label', K.C.text2); y += 26;
    if (data.busy && !data.fires) { K.shimmer(x, y, w, 72, 16); y += 84; }
    else if (data.err && !data.fires) { y += K.empty(K.W / 2, y + 10, 'alert', 'Offline', 'Fires will show when the wildfire service answers.', { w }) + 16; }
    else if (data.fires && !data.fires.length) { K.card(x, y, w, 64, { r: 16 }); K.icon('checkCircle', x + 30, y + 32, 20, K.C.good); K.text('No wildfires reported in range', x + 54, y + 37, 'body', K.C.text, { maxW: w - 70 }); y += 76; }
    else for (const [i, f] of (data.fires || []).entries()) {
      const n = notable(f), col = f.mi <= CLOSE_MI ? K.C.bad : n ? K.C.warn : K.C.text3;
      K.card(x, y, w, 72, { r: 16 });
      K.circle(x + 30, y + 36, 16, { fill: K.alpha(col, 0.18) }); K.icon('flame', x + 30, y + 36, 18, col);
      K.text((f.name || 'Unnamed') + ' Fire', x + 56, y + 30, 'headline', K.C.text, { maxW: w - 140 });
      K.text(acresText(f.acres) + (f.contained != null ? ' · ' + Math.round(f.contained) + '% contained' : ''), x + 56, y + 52, 'footnote', K.C.text3, { maxW: w - 140 });
      K.text(Math.round(f.mi) + ' mi', x + w - 16, y + 42, 'headline', col, { align: 'right' });
      y += 82; if (i > 20) break;
    }
    y += K.para('Notable fires (100 acres or more, or within 25 miles) are posted to Juli’s chat once each. Checks run while p0pc0rn is open. For evacuation orders, follow your local officials.', x, y + 6, w, 'footnote', K.C.text3) + 10;
  }
  K.text('Data: NIFC wildfire incidents (WFIGS)', x, y + 16, 'caption', K.C.text3);
  return y + 30 - y0;
}

function placePicker(x, y, w) {
  K.text('PLACE TO WATCH (US)', x, y + 14, 'label', K.C.text2); y += 24;
  ui.query = K.input('place', x, y, w - 96, 48, ui.query, { placeholder: 'Town or city', icon: 'pin', onEnter: search });
  if (K.button('find', x + w - 86, y, 86, 48, ui.searching ? '…' : 'Find', { style: 'primary', disabled: ui.searching })) search();
  y += 60;
  if (ui.results) for (const [i, r] of ui.results.entries()) {
    const row = K.listRow('res' + i, x, y, w, 56, { title: r.name, sub: [r.region, r.country].filter(Boolean).join(', '), icon: 'pin', iconColor: r.cc === 'US' ? ACCENT : K.C.text3, chevron: true, r: 14 });
    if (row.tap) choose(r);
    y += 62;
  }
  if (st.place && K.button('cancel', x, y + 4, w, 44, 'Keep ' + st.place.name, { style: 'ghost' })) { ui.editing = false; ui.results = null; K.blurInputs(); }
  return y + (st.place ? 60 : 12);
}
